import requests

from langflow.custom.custom_component.component import Component
from langflow.io import MessageTextInput, BoolInput, Output, SecretStrInput
from langflow.schema.message import Message


def _to_text(x) -> str:
    if isinstance(x, Message):
        return x.text or ""
    return str(x or "")


def _secret_to_text(x) -> str:
    if hasattr(x, "get_secret_value"):
        return x.get_secret_value()
    return _to_text(x)


class PublishZenodoDraftV2(Component):

    display_name = "Publish Zenodo Draft V2"
    description = "Validates and publishes a Zenodo draft. Returns SUCCESS(publish_zenodo_draft_v2) or ERROR only."
    icon = "rocket"
    name = "publish_zenodo_draft_v2"
    trace_type = "tool"

    inputs = [
        MessageTextInput(
            name="deposition_id",
            display_name="Deposition ID",
            tool_mode=True,
        ),
        SecretStrInput(
            name="zenodo_token",
            display_name="Zenodo API Token",
            required=True,
        ),
        BoolInput(
            name="use_sandbox",
            display_name="Use Sandbox",
            value=True,
            tool_mode=False,
        ),
    ]

    outputs = [
        Output(
            display_name="Message",
            name="message",
            method="publish_draft",
        ),
    ]

    def _error(self, msg: str) -> Message:
        text = f"ERROR(publish_zenodo_draft_v2): {msg}"
        self.status = text
        return Message(text=text)

    def _validate_metadata(self, deposition: dict) -> tuple[bool, list[str], dict]:
        metadata = deposition.get("metadata", {}) or {}

        title_ok = bool(str(metadata.get("title", "")).strip())
        description_ok = bool(str(metadata.get("description", "")).strip())
        upload_type_ok = bool(str(metadata.get("upload_type", "")).strip())

        creators = metadata.get("creators", [])
        creators_ok = isinstance(creators, list) and len(creators) > 0 and all(
            bool(str(c.get("name", "")).strip()) for c in creators if isinstance(c, dict)
        )

        missing = []
        if not title_ok:
            missing.append("metadata.title")
        if not description_ok:
            missing.append("metadata.description")
        if not upload_type_ok:
            missing.append("metadata.upload_type")
        if not creators_ok:
            missing.append("metadata.creators")

        validation = {
            "TITLE_OK": title_ok,
            "DESCRIPTION_OK": description_ok,
            "UPLOAD_TYPE_OK": upload_type_ok,
            "CREATORS_OK": creators_ok,
            "READY_TO_PUBLISH": len(missing) == 0,
        }

        return len(missing) == 0, missing, validation

    def publish_draft(self) -> Message:
        try:
            deposition_id = _to_text(self.deposition_id).strip()
            token = _secret_to_text(self.zenodo_token).strip()

            if not deposition_id:
                return self._error("deposition_id missing.")

            if not token:
                return self._error("Zenodo API token missing.")

            base_url = (
                "https://sandbox.zenodo.org/api/deposit/depositions"
                if self.use_sandbox
                else "https://zenodo.org/api/deposit/depositions"
            )

            headers = {
                "Authorization": f"Bearer {token}",
            }

            deposition_url = f"{base_url}/{deposition_id}"

            # 1. GET current draft metadata before publishing
            get_response = requests.get(
                deposition_url,
                headers=headers,
                timeout=60,
            )

            if get_response.status_code not in [200, 201]:
                return self._error(
                    f"Could not read draft before publishing. "
                    f"HTTP {get_response.status_code}. "
                    f"Response: {get_response.text[:1000]}"
                )

            deposition = get_response.json()

            metadata_ok, missing_metadata, validation = self._validate_metadata(deposition)

            validation_text = "\n".join(
                f"{key}: {value}" for key, value in validation.items()
            )

            if not metadata_ok:
                return self._error(
                    "Draft is NOT ready to publish. Missing required metadata: "
                    + ", ".join(missing_metadata)
                    + "\nRun edit_zenodo_draft first, or recreate the draft using create_zenodo_draft_v3.\n\n"
                    + "Metadata validation:\n"
                    + validation_text
                )

            # 2. Publish only after validation passes
            publish_url = f"{base_url}/{deposition_id}/actions/publish"

            publish_response = requests.post(
                publish_url,
                headers=headers,
                timeout=120,
            )

            if publish_response.status_code not in [200, 201, 202]:
                return self._error(
                    f"Zenodo publish failed. "
                    f"HTTP {publish_response.status_code}. "
                    f"Response: {publish_response.text[:1500]}"
                )

            data = publish_response.json()

            doi = data.get("doi", "N/A")
            record_url = (
                data.get("links", {}).get("record_html")
                or data.get("links", {}).get("html")
                or "N/A"
            )

            environment_name = (
                "Zenodo Sandbox"
                if self.use_sandbox
                else "Zenodo Production"
            )

            result = f"""SUCCESS(publish_zenodo_draft_v2)

[Zenodo DOI Published]

Deposition ID:
{deposition_id}

Published DOI:
{doi}

Record URL:
{record_url}

Environment:
{environment_name}

Metadata validation before publish:
{validation_text}

Important:
This DOI is now published in the selected environment.

Published records should be treated as persistent scholarly artifacts.

Files should not be modified after publication. For new files or changed scientific content, create a new version.

Debug:
TOOL_NAME: publish_zenodo_draft_v2
USE_SANDBOX: {self.use_sandbox}
"""

            self.status = result
            return Message(text=result)

        except Exception as e:
            return self._error(f"{type(e).__name__}: {e}")

import json
import requests

from langflow.custom.custom_component.component import Component
from langflow.io import MessageTextInput, BoolInput, Output, SecretStrInput
from langflow.schema.message import Message


def _to_text(x) -> str:
    if isinstance(x, Message):
        return x.text or ""
    return str(x or "")


def _secret_to_text(x) -> str:
    if hasattr(x, "get_secret_value"):
        return x.get_secret_value()
    return _to_text(x)


def _parse_csv(text: str):
    return [x.strip() for x in (text or "").split(",") if x.strip()]


def _parse_creators(text: str):
    creators = []

    for item in (text or "").split(";"):
        item = item.strip()
        if not item:
            continue

        if "|" in item:
            name, affiliation = item.split("|", 1)
            creator = {"name": name.strip()}
            if affiliation.strip():
                creator["affiliation"] = affiliation.strip()
            creators.append(creator)
        else:
            creators.append({"name": item})

    return creators


class EditPublishedZenodoMetadataV2(Component):

    display_name = "Edit Published Zenodo Metadata V2"
    description = "Safely edits published Zenodo metadata while preserving required existing fields like creators."
    icon = "database"
    name = "edit_published_zenodo_metadata_v2"
    trace_type = "tool"

    inputs = [
        MessageTextInput(name="deposition_id", display_name="Deposition ID", tool_mode=True),
        MessageTextInput(name="title", display_name="Updated Title", tool_mode=True),
        MessageTextInput(name="description", display_name="Updated Description", tool_mode=True),
        MessageTextInput(name="creators", display_name="Creators optional, semicolon-separated, use Name|Affiliation", tool_mode=True),
        MessageTextInput(name="keywords", display_name="Keywords optional, comma-separated", tool_mode=True),
        MessageTextInput(name="version", display_name="Version optional", tool_mode=True),
        MessageTextInput(name="license_id", display_name="License optional", tool_mode=True),
        SecretStrInput(name="zenodo_token", display_name="Zenodo API Token", required=True),
        BoolInput(name="use_sandbox", display_name="Use Sandbox", value=True, tool_mode=False),
    ]

    outputs = [
        Output(display_name="Message", name="message", method="edit_metadata"),
    ]

    def _error(self, msg: str) -> Message:
        text = f"ERROR(edit_published_zenodo_metadata_v2): {msg}"
        self.status = text
        return Message(text=text)

    def edit_metadata(self) -> Message:
        try:
            deposition_id = _to_text(self.deposition_id).strip()
            token = _secret_to_text(self.zenodo_token).strip()

            new_title = _to_text(self.title).strip()
            new_description = _to_text(self.description).strip()
            new_creators_text = _to_text(self.creators).strip()
            new_keywords_text = _to_text(self.keywords).strip()
            new_version = _to_text(self.version).strip()
            new_license = _to_text(self.license_id).strip()

            if not deposition_id:
                return self._error("deposition_id missing.")

            if not token:
                return self._error("Zenodo API token missing.")

            base_url = (
                "https://sandbox.zenodo.org/api/deposit/depositions"
                if self.use_sandbox
                else "https://zenodo.org/api/deposit/depositions"
            )

            headers = {
                "Authorization": f"Bearer {token}",
                "Content-Type": "application/json",
            }

            auth_headers = {
                "Authorization": f"Bearer {token}",
            }

            deposition_url = f"{base_url}/{deposition_id}"

            # 1. Unlock published record for editing.
            edit_url = f"{base_url}/{deposition_id}/actions/edit"

            edit_response = requests.post(
                edit_url,
                headers=auth_headers,
                timeout=120,
            )

            if edit_response.status_code not in [200, 201, 202]:
                return self._error(
                    f"Could not unlock published record for editing. "
                    f"HTTP {edit_response.status_code}. "
                    f"Response: {edit_response.text[:1500]}"
                )

            # 2. GET existing draft metadata after unlocking.
            get_response = requests.get(
                deposition_url,
                headers=auth_headers,
                timeout=60,
            )

            if get_response.status_code not in [200, 201]:
                return self._error(
                    f"Could not read editable draft metadata. "
                    f"HTTP {get_response.status_code}. "
                    f"Response: {get_response.text[:1500]}"
                )

            current = get_response.json()
            current_metadata = current.get("metadata", {}) or {}

            # 3. Preserve required existing metadata unless user overrides.
            preserved_title = current_metadata.get("title", "")
            preserved_description = current_metadata.get("description", "")
            preserved_upload_type = current_metadata.get("upload_type", "dataset")
            preserved_creators = current_metadata.get("creators", [])
            preserved_keywords = current_metadata.get("keywords", [])
            preserved_license = current_metadata.get("license", "cc-by-4.0")
            preserved_version = current_metadata.get("version", "1.0")
            preserved_access_right = current_metadata.get("access_right", "open")

            final_creators = (
                _parse_creators(new_creators_text)
                if new_creators_text
                else preserved_creators
            )

            final_keywords = (
                _parse_csv(new_keywords_text)
                if new_keywords_text
                else preserved_keywords
            )

            final_metadata = {
                "title": new_title or preserved_title,
                "upload_type": preserved_upload_type or "dataset",
                "description": new_description or preserved_description,
                "creators": final_creators,
                "keywords": final_keywords,
                "license": new_license or preserved_license or "cc-by-4.0",
                "version": new_version or preserved_version or "1.0",
                "access_right": preserved_access_right or "open",
            }

            # 4. Validate before PUT.
            missing = []
            if not final_metadata["title"]:
                missing.append("metadata.title")
            if not final_metadata["description"]:
                missing.append("metadata.description")
            if not final_metadata["upload_type"]:
                missing.append("metadata.upload_type")
            if not final_metadata["creators"]:
                missing.append("metadata.creators")

            if missing:
                return self._error(
                    "Cannot update published metadata because required fields are missing after preservation: "
                    + ", ".join(missing)
                    + ". Provide creators explicitly, e.g. Nano|MIT."
                )

            payload = {"metadata": final_metadata}

            # 5. Update metadata.
            update_response = requests.put(
                deposition_url,
                headers=headers,
                json=payload,
                timeout=120,
            )

            if update_response.status_code not in [200, 201]:
                return self._error(
                    f"Metadata update failed. "
                    f"HTTP {update_response.status_code}. "
                    f"Response: {update_response.text[:1500]}"
                )

            # 6. Republish metadata edits.
            publish_url = f"{base_url}/{deposition_id}/actions/publish"

            publish_response = requests.post(
                publish_url,
                headers=auth_headers,
                timeout=120,
            )

            if publish_response.status_code not in [200, 201, 202]:
                return self._error(
                    f"Metadata updated but republish failed. "
                    f"HTTP {publish_response.status_code}. "
                    f"Response: {publish_response.text[:1500]}"
                )

            data = publish_response.json()

            doi = data.get("doi", "N/A")
            record_url = (
                data.get("links", {}).get("record_html")
                or data.get("links", {}).get("html")
                or "N/A"
            )

            environment_name = "Sandbox" if self.use_sandbox else "Production"

            result = f"""SUCCESS(edit_published_zenodo_metadata_v2)

[Published Zenodo Metadata Updated]

Deposition ID:
{deposition_id}

DOI:
{doi}

Record URL:
{record_url}

Environment:
{environment_name}

Updated title:
{final_metadata["title"]}

Version:
{final_metadata["version"]}

Creators preserved/used:
{json.dumps(final_metadata["creators"], indent=2, ensure_ascii=False)}

Important:
The DOI identifier remains unchanged.

Only metadata was modified.

Published files were not altered.

Debug:
TOOL_NAME: edit_published_zenodo_metadata_v2
CREATORS_COUNT: {len(final_metadata["creators"])}
"""

            self.status = result
            return Message(text=result)

        except Exception as e:
            return self._error(f"{type(e).__name__}: {e}")

import json
import sqlite3
from pathlib import Path
from typing import List

import requests

from langflow.custom.custom_component.component import Component
from langflow.io import (
    BoolInput,
    DropdownInput,
    MessageTextInput,
    Output,
    SecretStrInput,
)
from langflow.schema.message import Message


def _to_text(x) -> str:
    if isinstance(x, Message):
        return x.text or ""
    return str(x or "")


def _secret_to_text(x) -> str:
    if hasattr(x, "get_secret_value"):
        return x.get_secret_value()
    return _to_text(x)


def _parse_csv(text: str) -> List[str]:
    return [x.strip() for x in (text or "").split(",") if x.strip()]


def _parse_creators(text: str) -> List[dict]:
    creators = []

    for item in (text or "").split(";"):
        item = item.strip()
        if not item:
            continue

        if "|" in item:
            name, affiliation = item.split("|", 1)
            creator = {"name": name.strip()}

            if affiliation.strip():
                creator["affiliation"] = affiliation.strip()

            creators.append(creator)
        else:
            creators.append({"name": item.strip()})

    return creators


def _utc_now() -> str:
    from datetime import datetime, timezone
    return datetime.now(timezone.utc).isoformat()


def _get_registry_row(db_path: Path, run_id: str):
    if not db_path.exists():
        return None

    with sqlite3.connect(db_path) as conn:
        conn.row_factory = sqlite3.Row
        row = conn.execute(
            "SELECT * FROM madvi_runs WHERE run_id = ?",
            (run_id,),
        ).fetchone()

    return dict(row) if row else None


def _update_registry_zenodo(db_path: Path, run_id: str, deposition_id: str, reserved_doi: str, status: str):
    if not db_path.exists():
        return

    with sqlite3.connect(db_path) as conn:
        conn.execute(
            """
            UPDATE madvi_runs
            SET deposition_id = ?, reserved_doi = ?, status = ?, updated_at = ?
            WHERE run_id = ?
            """,
            (deposition_id, reserved_doi, status, _utc_now(), run_id),
        )
        conn.commit()


class CreateZenodoDraftV4(Component):
    display_name = "Create Zenodo Draft V5"
    description = "Creates Zenodo draft from file path or registry run_id, validates metadata, and updates registry."
    icon = "upload-cloud"
    name = "create_zenodo_draft_v5"
    trace_type = "tool"

    REGISTRY_DB = "/home/domo/Langflow311/madvi_registry.db"

    inputs = [
        MessageTextInput(name="title", display_name="Title", tool_mode=True),
        MessageTextInput(name="creators", display_name="Creators", tool_mode=True),
        MessageTextInput(name="description", display_name="Description", tool_mode=True),

        MessageTextInput(name="file_paths", display_name="File or folder paths comma-separated optional", tool_mode=True),
        MessageTextInput(name="run_id", display_name="Run ID optional", tool_mode=True),
        MessageTextInput(name="registry_db", display_name="Registry DB optional", tool_mode=True),

        MessageTextInput(name="keywords", display_name="Keywords comma-separated", tool_mode=True, value="Madrigal,FAIR,Reproducibility,Metadata"),
        MessageTextInput(name="license_id", display_name="License ID", tool_mode=True, value="cc-by-4.0"),
        MessageTextInput(name="version", display_name="Version", tool_mode=True, value="1.0"),

        DropdownInput(
            name="upload_type",
            display_name="Upload Type",
            options=["dataset", "software", "publication", "poster", "presentation", "report"],
            value="dataset",
            tool_mode=True,
        ),
        DropdownInput(
            name="access_right",
            display_name="Access Right",
            options=["open", "restricted", "closed"],
            value="open",
            tool_mode=True,
        ),
        BoolInput(name="use_sandbox", display_name="Use Zenodo Sandbox", value=True, tool_mode=True),
        SecretStrInput(name="zenodo_token", display_name="Zenodo API Token", required=True),
    ]

    outputs = [
        Output(display_name="Message", name="message", method="create_draft"),
    ]

    def _error(self, msg: str) -> Message:
        text = f"ERROR(create_zenodo_draft_v4): {msg}"
        self.status = text
        return Message(text=text)

    def _collect_files(self, paths: List[str]) -> List[Path]:
        collected = []

        for raw in paths:
            p = Path(raw.strip().strip('"').strip("'"))

            if not p.exists():
                raise FileNotFoundError(f"Path does not exist: {p}")

            if p.is_file():
                collected.append(p)

            elif p.is_dir():
                for child in p.rglob("*"):
                    if child.is_file():
                        collected.append(child)

        return collected

    def _validate_metadata(self, deposition: dict):
        metadata = deposition.get("metadata", {}) or {}

        title_ok = bool(str(metadata.get("title", "")).strip())
        description_ok = bool(str(metadata.get("description", "")).strip())
        upload_type_ok = bool(str(metadata.get("upload_type", "")).strip())

        creators = metadata.get("creators", [])
        creators_ok = (
            isinstance(creators, list)
            and len(creators) > 0
            and all(isinstance(c, dict) and bool(str(c.get("name", "")).strip()) for c in creators)
        )

        missing = []
        if not title_ok:
            missing.append("metadata.title")
        if not description_ok:
            missing.append("metadata.description")
        if not upload_type_ok:
            missing.append("metadata.upload_type")
        if not creators_ok:
            missing.append("metadata.creators")

        validation = {
            "TITLE_OK": title_ok,
            "DESCRIPTION_OK": description_ok,
            "UPLOAD_TYPE_OK": upload_type_ok,
            "CREATORS_OK": creators_ok,
            "READY_TO_PUBLISH": len(missing) == 0,
        }

        return len(missing) == 0, missing, validation

    def create_draft(self) -> Message:
        try:
            title = _to_text(self.title).strip()
            creators_text = _to_text(self.creators).strip()
            description = _to_text(self.description).strip()
            file_paths_text = _to_text(self.file_paths).strip()
            run_id = _to_text(self.run_id).strip()
            registry_db = Path(_to_text(self.registry_db).strip() or self.REGISTRY_DB)

            if not file_paths_text and run_id:
                row = _get_registry_row(registry_db, run_id)
                if row:
                    file_paths_text = row.get("package_path", "")

            keywords = _parse_csv(_to_text(self.keywords))
            license_id = _to_text(self.license_id).strip() or "cc-by-4.0"
            version = _to_text(self.version).strip() or "1.0"
            upload_type = _to_text(self.upload_type).strip() or "dataset"
            access_right = _to_text(self.access_right).strip() or "open"
            use_sandbox = bool(self.use_sandbox)
            token = _secret_to_text(self.zenodo_token).strip()

            missing = []
            if not title:
                missing.append("title")
            if not creators_text:
                missing.append("creators")
            if not description:
                missing.append("description")
            if not file_paths_text:
                missing.append("file_paths or valid run_id")
            if not token:
                missing.append("zenodo_token")

            if missing:
                return self._error("Missing required fields: " + ", ".join(missing))

            creators = _parse_creators(creators_text)

            if not creators:
                return self._error("Could not parse creators. Use format: Nano|MIT or Doe, Jane|MIT; Smith, John|Haystack.")

            files = self._collect_files(_parse_csv(file_paths_text))

            if not files:
                return self._error("No files found in provided paths.")

            base_url = (
                "https://sandbox.zenodo.org/api/deposit/depositions"
                if use_sandbox
                else "https://zenodo.org/api/deposit/depositions"
            )

            auth_headers = {"Authorization": f"Bearer {token}"}
            json_headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}

            create_response = requests.post(base_url, headers=auth_headers, json={}, timeout=60)

            if create_response.status_code not in [200, 201]:
                return self._error(
                    f"Zenodo deposition creation failed. HTTP {create_response.status_code}. Response: {create_response.text[:1000]}"
                )

            deposition = create_response.json()
            deposition_id = deposition.get("id")
            bucket_url = deposition.get("links", {}).get("bucket")

            if not deposition_id or not bucket_url:
                return self._error(f"Deposition created but missing id or bucket URL. Response: {str(deposition)[:1000]}")

            uploaded_files = []

            for file_path in files:
                with open(file_path, "rb") as fp:
                    upload_response = requests.put(
                        f"{bucket_url}/{file_path.name}",
                        data=fp,
                        headers=auth_headers,
                        timeout=300,
                    )

                if upload_response.status_code not in [200, 201]:
                    return self._error(
                        f"File upload failed for {file_path.name}. HTTP {upload_response.status_code}. Response: {upload_response.text[:1000]}"
                    )

                uploaded_files.append(file_path.name)

            metadata_payload = {
                "metadata": {
                    "title": title,
                    "upload_type": upload_type,
                    "description": description,
                    "creators": creators,
                    "access_right": access_right,
                    "license": license_id,
                    "keywords": keywords,
                    "version": version,
                    "prereserve_doi": {},
                }
            }

            metadata_url = f"{base_url}/{deposition_id}"

            metadata_response = requests.put(
                metadata_url,
                headers=json_headers,
                json=metadata_payload,
                timeout=60,
            )

            if metadata_response.status_code not in [200, 201]:
                return self._error(
                    f"Metadata update failed. HTTP {metadata_response.status_code}. Response: {metadata_response.text[:1500]}"
                )

            get_response = requests.get(metadata_url, headers=auth_headers, timeout=60)

            if get_response.status_code not in [200, 201]:
                return self._error(
                    f"Metadata verification GET failed. HTTP {get_response.status_code}. Response: {get_response.text[:1000]}"
                )

            final_data = get_response.json()
            metadata_ok, missing_metadata, validation = self._validate_metadata(final_data)

            validation_text = "\n".join(f"{key}: {value}" for key, value in validation.items())

            if not metadata_ok:
                return self._error(
                    "Draft created but NOT ready to publish. Missing required metadata after verification: "
                    + ", ".join(missing_metadata)
                    + "\nMetadata validation:\n"
                    + validation_text
                )

            draft_html = final_data.get("links", {}).get("html", "N/A")

            reserved_doi = (
                final_data.get("metadata", {})
                .get("prereserve_doi", {})
                .get("doi", "N/A")
            )

            if run_id:
