import json
import requests

from langflow.custom.custom_component.component import Component
from langflow.io import MessageTextInput, BoolInput, Output, SecretStrInput
from langflow.schema.message import Message


def _to_text(x) -> str:
    if isinstance(x, Message):
        return x.text or ""
    return str(x or "")


def _secret_to_text(x) -> str:
    if hasattr(x, "get_secret_value"):
        return x.get_secret_value()
    return _to_text(x)


def _parse_csv(text: str):
    return [x.strip() for x in (text or "").split(",") if x.strip()]


def _parse_creators(text: str):
    """
    Creator format:
      Nano
      Nano|MIT
      Doe, Jane|MIT; Smith, John|Haystack

    Rules:
      ; separates creators
      | separates name from affiliation
    """
    creators = []

    for item in (text or "").split(";"):
        item = item.strip()

        if not item:
            continue

        if "|" in item:
            name, affiliation = item.split("|", 1)
            name = name.strip()
            affiliation = affiliation.strip()

            if name:
                creator = {"name": name}
                if affiliation:
                    creator["affiliation"] = affiliation
                creators.append(creator)

        else:
            name = item.strip()
            if name:
                creators.append({"name": name})

    return creators


class EditZenodoDraft(Component):

    display_name = "Edit Zenodo Draft v2"
    description = "Safely edits metadata of an existing unpublished Zenodo draft while preserving required fields."
    icon = "file-edit"
    name = "edit_zenodo_draft_v2"
    trace_type = "tool"

    inputs = [
        MessageTextInput(
            name="deposition_id",
            display_name="Deposition ID",
            tool_mode=True,
        ),

        MessageTextInput(
            name="title",
            display_name="Updated Title optional",
            tool_mode=True,
        ),

        MessageTextInput(
            name="creators",
            display_name="Creators optional, semicolon-separated, use Name|Affiliation",
            tool_mode=True,
        ),

        MessageTextInput(
            name="description",
            display_name="Updated Description optional",
            tool_mode=True,
        ),

        MessageTextInput(
            name="keywords",
            display_name="Keywords optional, comma-separated",
            tool_mode=True,
        ),

        MessageTextInput(
            name="version",
            display_name="Version optional",
            tool_mode=True,
        ),

        MessageTextInput(
            name="license_id",
            display_name="License optional",
            tool_mode=True,
        ),

        SecretStrInput(
            name="zenodo_token",
            display_name="Zenodo API Token",
            required=True,
        ),

        BoolInput(
            name="use_sandbox",
            display_name="Use Sandbox",
            value=True,
            tool_mode=False,
        ),
    ]

    outputs = [
        Output(
            display_name="Message",
            name="message",
            method="edit_draft",
        ),
    ]

    def _error(self, msg: str) -> Message:
        text = f"ERROR(edit_zenodo_draft): {msg}"
        self.status = text
        return Message(text=text)

    def _validate_metadata(self, metadata: dict):
        title_ok = bool(str(metadata.get("title", "")).strip())
        description_ok = bool(str(metadata.get("description", "")).strip())
        upload_type_ok = bool(str(metadata.get("upload_type", "")).strip())

        creators = metadata.get("creators", [])
        creators_ok = (
            isinstance(creators, list)
            and len(creators) > 0
            and all(
                isinstance(c, dict)
                and bool(str(c.get("name", "")).strip())
                for c in creators
            )
        )

        missing = []

        if not title_ok:
            missing.append("metadata.title")

        if not description_ok:
            missing.append("metadata.description")

        if not upload_type_ok:
            missing.append("metadata.upload_type")

        if not creators_ok:
            missing.append("metadata.creators")

        validation = {
            "TITLE_OK": title_ok,
            "DESCRIPTION_OK": description_ok,
            "UPLOAD_TYPE_OK": upload_type_ok,
            "CREATORS_OK": creators_ok,
            "READY_TO_PUBLISH": len(missing) == 0,
        }

        return len(missing) == 0, missing, validation

    def edit_draft(self) -> Message:

        try:
            deposition_id = _to_text(self.deposition_id).strip()
            token = _secret_to_text(self.zenodo_token).strip()

            new_title = _to_text(self.title).strip()
            new_description = _to_text(self.description).strip()
            new_creators_text = _to_text(self.creators).strip()
            new_keywords_text = _to_text(self.keywords).strip()
            new_version = _to_text(self.version).strip()
            new_license = _to_text(self.license_id).strip()

            if not deposition_id:
                return self._error("deposition_id missing.")

            if not token:
                return self._error("Zenodo API token missing.")

            base_url = (
                "https://sandbox.zenodo.org/api/deposit/depositions"
                if self.use_sandbox
                else "https://zenodo.org/api/deposit/depositions"
            )

            deposition_url = f"{base_url}/{deposition_id}"

            auth_headers = {
                "Authorization": f"Bearer {token}",
            }

            json_headers = {
                "Authorization": f"Bearer {token}",
                "Content-Type": "application/json",
            }


            get_response = requests.get(
                deposition_url,
                headers=auth_headers,
                timeout=60,
            )

            if get_response.status_code not in [200, 201]:
                return self._error(
                    f"Could not read Zenodo draft. "
                    f"HTTP {get_response.status_code}. "
                    f"Response: {get_response.text[:1500]}"
                )

            current = get_response.json()
            current_metadata = current.get("metadata", {}) or {}

            # 2. Preserve existing metadata unless user explicitly overrides.
            preserved_title = current_metadata.get("title", "")
            preserved_description = current_metadata.get("description", "")
            preserved_upload_type = current_metadata.get("upload_type", "dataset")
            preserved_creators = current_metadata.get("creators", [])
            preserved_keywords = current_metadata.get("keywords", [])
            preserved_license = current_metadata.get("license", "cc-by-4.0")
            preserved_version = current_metadata.get("version", "1.0")
            preserved_access_right = current_metadata.get("access_right", "open")

            if new_creators_text:
                final_creators = _parse_creators(new_creators_text)
            else:
                final_creators = preserved_creators

            if new_keywords_text:
                final_keywords = _parse_csv(new_keywords_text)
            else:
                final_keywords = preserved_keywords

            final_metadata = {
                "title": new_title or preserved_title,
                "upload_type": preserved_upload_type or "dataset",
                "description": new_description or preserved_description,
                "creators": final_creators,
                "keywords": final_keywords,
                "license": new_license or preserved_license or "cc-by-4.0",
                "version": new_version or preserved_version or "1.0",
                "access_right": preserved_access_right or "open",
            }


            if "prereserve_doi" in current_metadata:
                final_metadata["prereserve_doi"] = current_metadata["prereserve_doi"]

            metadata_ok, missing_metadata, validation = self._validate_metadata(final_metadata)

            validation_text = "\n".join(
                f"{key}: {value}" for key, value in validation.items()
            )

            if not metadata_ok:
                return self._error(
                    "Cannot update draft because required metadata would be missing: "
                    + ", ".join(missing_metadata)
                    + "\nProvide missing fields explicitly, for example creators: Nano|MIT.\n\n"
                    + "Metadata validation:\n"
                    + validation_text
                )

            payload = {
                "metadata": final_metadata
            }


            update_response = requests.put(
                deposition_url,
                headers=json_headers,
                json=payload,
                timeout=120,
            )

            if update_response.status_code not in [200, 201]:
                return self._error(
                    f"Metadata update failed. "
                    f"HTTP {update_response.status_code}. "
                    f"Response: {update_response.text[:1500]}"
                )

            updated = update_response.json()
            updated_metadata = updated.get("metadata", {}) or {}


            stored_ok, stored_missing, stored_validation = self._validate_metadata(updated_metadata)

            stored_validation_text = "\n".join(
                f"{key}: {value}" for key, value in stored_validation.items()
            )

            if not stored_ok:
                return self._error(
                    "Draft updated, but Zenodo-stored metadata is still incomplete: "
                    + ", ".join(stored_missing)
                    + "\n\nStored metadata validation:\n"
                    + stored_validation_text
                )

            draft_url = (
                updated.get("links", {}).get("html")
                or updated.get("links", {}).get("latest_draft")
                or "N/A"
            )

            reserved_doi = (
                updated_metadata
                .get("prereserve_doi", {})
                .get("doi", "N/A")
                if isinstance(updated_metadata.get("prereserve_doi", {}), dict)
                else "N/A"
            )

            environment_name = (
                "Zenodo Sandbox"
                if self.use_sandbox
                else "Zenodo Production"
            )

            result = f"""SUCCESS(edit_zenodo_draft)

[Zenodo Draft Edited]

Deposition ID:
{deposition_id}

Environment:
{environment_name}

Draft URL:
{draft_url}

Reserved DOI:
{reserved_doi}

Updated title:
{updated_metadata.get("title", "N/A")}

Version:
{updated_metadata.get("version", "N/A")}

Creators preserved/used:
{json.dumps(updated_metadata.get("creators", []), indent=2, ensure_ascii=False)}

Metadata validation:
{stored_validation_text}

Important:
This is still an unpublished Zenodo draft.

Editing metadata does not publish the DOI.

Debug:
TOOL_NAME: edit_zenodo_draft
CREATORS_COUNT: {len(updated_metadata.get("creators", []))}
USE_SANDBOX: {self.use_sandbox}
"""

            self.status = result

            return Message(text=result)

        except Exception as e:

            return self._error(f"{type(e).__name__}: {e}")

