        "neutral_wind": "neutral wind",
        "neutral_wind_errors": "neutral wind errors",
        "magnetic_meridional_neutral_wind": "magnetic meridional neutral wind",
    }
    return ", ".join(label_map.get(x, x) for x in intents)


