DEFAULT_MADRIGAL_URL = "https://cedar.openmadrigal.org/"


def _to_text(x) -> str:
    if isinstance(x, Message):
        return x.text or ""
    return str(x or "")


def _secret_to_text(x) -> str:
    if hasattr(x, "get_secret_value"):
        return x.get_secret_value()
    return _to_text(x)


def _clean_space(text: str) -> str:
    return re.sub(r"\s+", " ", str(text or "").strip())


def _norm(text: str) -> str:
    return _clean_space(text).lower()


def _contains_any(q: str, terms: List[str]) -> bool:
    return any(t in q for t in terms)


def _extract_limit(query: str, default_limit: int = 15) -> int:
    m = re.search(r"\btop\s+(\d+)\b", query.lower())
    if m:
        try:
            return max(1, min(500, int(m.group(1))))
        except Exception:
            pass
    return default_limit


def _extract_year(query: str) -> Optional[str]:
    m = re.search(r"\b(20\d{2}|19\d{2})\b", query or "")
    return m.group(1) if m else None




MONTH_NAME_TO_NUMBER: Dict[str, int] = {
    "january": 1, "jan": 1,
    "february": 2, "feb": 2,
    "march": 3, "mar": 3,
    "april": 4, "apr": 4,
    "may": 5,
    "june": 6, "jun": 6,
    "july": 7, "jul": 7,
    "august": 8, "aug": 8,
    "september": 9, "sep": 9, "sept": 9,
    "october": 10, "oct": 10,
    "november": 11, "nov": 11,
    "december": 12, "dec": 12,
}


def _iso_utc(dt: datetime) -> str:
    return dt.strftime("%Y-%m-%dT%H:%M:%S+00:00")


def _strip_ordinal_suffixes(text: str) -> str:
    return re.sub(r"(\d+)(st|nd|rd|th)\b", r"\1", text or "", flags=re.I)


def _parse_flexible_date(value: str) -> Optional[datetime]:
    """
    Parse one calendar date without inventing a timezone.
    Returned datetimes are naive UTC calendar boundaries.
    """
    value = _strip_ordinal_suffixes(value or "")
    value = re.sub(r"\s+", " ", value.strip().strip(",.;"))

    if not value:
        return None

    formats = [
        "%Y-%m-%d",
        "%Y/%m/%d",
        "%m/%d/%Y",
        "%m-%d-%Y",
        "%B %d %Y",
        "%b %d %Y",
        "%B %d, %Y",
        "%b %d, %Y",
    ]

    for fmt in formats:
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            continue

    return None


def _extract_sql_time_window(query: str) -> Optional[Dict[str, str]]:
    """
    Convert a user time expression into an inclusive-start/exclusive-end UTC window.

    Supported examples:
      - 2019
      - August 2019 / Aug 2019
      - 2019-08
      - 2019-08-01
      - 08/01/2019
      - from 2019-08-01 to 2019-08-31
      - between August 1 and August 31, 2019
    """
    raw = _strip_ordinal_suffixes(query or "")
    q = _norm(raw)

    # Defensive local month map.
    # Langflow may compile helper functions in an isolated namespace after a
    # custom-component edit, which can make module-level constants unavailable
    # even when they are present in the source. Keeping this mapping local
    # prevents NameError: MONTH_NAME_TO_NUMBER is not defined.
    month_name_to_number = {
        "january": 1, "jan": 1,
        "february": 2, "feb": 2,
        "march": 3, "mar": 3,
        "april": 4, "apr": 4,
        "may": 5,
        "june": 6, "jun": 6,
        "july": 7, "jul": 7,
        "august": 8, "aug": 8,
        "september": 9, "sep": 9, "sept": 9,
        "october": 10, "oct": 10,
        "november": 11, "nov": 11,
        "december": 12, "dec": 12,
    }

    # Explicit ISO or slash-form date pairs.
    date_tokens = re.findall(
        r"\b(?:19|20)\d{2}[-/]\d{1,2}[-/]\d{1,2}\b"
        r"|\b\d{1,2}/\d{1,2}/(?:19|20)\d{2}\b",
        raw,
        flags=re.I,
    )

    if len(date_tokens) >= 2:
        start_dt = _parse_flexible_date(date_tokens[0])
        end_dt = _parse_flexible_date(date_tokens[1])
        if start_dt and end_dt:
            if end_dt < start_dt:
                start_dt, end_dt = end_dt, start_dt
            end_exclusive = end_dt + timedelta(days=1)
            return {
                "start": _iso_utc(start_dt),
                "end": _iso_utc(end_exclusive),
                "label": f"{start_dt:%Y-%m-%d} through {end_dt:%Y-%m-%d}",
                "granularity": "date_range",
            }

    # Two full month-name dates, each carrying its own year.
    month_date_pattern = (
        r"\b(?:january|february|march|april|may|june|july|august|"
        r"september|october|november|december|jan|feb|mar|apr|jun|jul|"
        r"aug|sep|sept|oct|nov|dec)\s+\d{1,2}(?:,\s*|\s+)(?:19|20)\d{2}\b"
    )
    named_dates = re.findall(month_date_pattern, raw, flags=re.I)
    if len(named_dates) >= 2:
        start_dt = _parse_flexible_date(named_dates[0])
        end_dt = _parse_flexible_date(named_dates[1])
        if start_dt and end_dt:
            if end_dt < start_dt:
                start_dt, end_dt = end_dt, start_dt
            end_exclusive = end_dt + timedelta(days=1)
            return {
                "start": _iso_utc(start_dt),
                "end": _iso_utc(end_exclusive),
                "label": f"{start_dt:%Y-%m-%d} through {end_dt:%Y-%m-%d}",
                "granularity": "date_range",
            }

    # Same-month or cross-month phrase where the year appears once:
    # "between August 1 and August 31, 2019"
    m = re.search(
        r"\b(?:from|between)\s+"
        r"(january|february|march|april|may|june|july|august|september|october|november|december|"
        r"jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\s+(\d{1,2})\s+"
        r"(?:to|through|until|and|-)\s+"
        r"(?:(january|february|march|april|may|june|july|august|september|october|november|december|"
        r"jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\s+)?"
        r"(\d{1,2})(?:,\s*|\s+)((?:19|20)\d{2})\b",
        raw,
        flags=re.I,
    )
    if m:
        month1 = month_name_to_number[m.group(1).lower()]
        month2 = month_name_to_number[(m.group(3) or m.group(1)).lower()]
        year = int(m.group(5))
        try:
            start_dt = datetime(year, month1, int(m.group(2)))
            end_dt = datetime(year, month2, int(m.group(4)))
            if end_dt < start_dt:
                start_dt, end_dt = end_dt, start_dt
            return {
                "start": _iso_utc(start_dt),
                "end": _iso_utc(end_dt + timedelta(days=1)),
                "label": f"{start_dt:%Y-%m-%d} through {end_dt:%Y-%m-%d}",
                "granularity": "date_range",
            }
        except ValueError:
            pass

    # One exact date means one UTC calendar day.
    if len(date_tokens) == 1:
        day = _parse_flexible_date(date_tokens[0])
        if day:
            return {
                "start": _iso_utc(day),
                "end": _iso_utc(day + timedelta(days=1)),
                "label": f"{day:%Y-%m-%d}",
                "granularity": "day",
            }

    if len(named_dates) == 1:
        day = _parse_flexible_date(named_dates[0])
        if day:
            return {
                "start": _iso_utc(day),
                "end": _iso_utc(day + timedelta(days=1)),
                "label": f"{day:%Y-%m-%d}",
                "granularity": "day",
            }

    # Numeric year-month, e.g. 2019-08.
    m = re.search(r"\b((?:19|20)\d{2})[-/](0?[1-9]|1[0-2])\b", raw)
    if m:
        year = int(m.group(1))
        month = int(m.group(2))
        start_dt = datetime(year, month, 1)
        if month == 12:
            end_dt = datetime(year + 1, 1, 1)
        else:
            end_dt = datetime(year, month + 1, 1)
        return {
            "start": _iso_utc(start_dt),
            "end": _iso_utc(end_dt),
            "label": f"{calendar.month_name[month]} {year}",
            "granularity": "month",
        }

    # Month name + year, e.g. August 2019.
    m = re.search(
        r"\b(january|february|march|april|may|june|july|august|september|october|november|december|"
        r"jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\s+(?:of\s+)?((?:19|20)\d{2})\b",
        q,
        flags=re.I,
    )
    if m:
        month = month_name_to_number[m.group(1).lower()]
        year = int(m.group(2))
        start_dt = datetime(year, month, 1)
        if month == 12:
            end_dt = datetime(year + 1, 1, 1)
        else:
            end_dt = datetime(year, month + 1, 1)
        return {
            "start": _iso_utc(start_dt),
            "end": _iso_utc(end_dt),
            "label": f"{calendar.month_name[month]} {year}",
            "granularity": "month",
        }

    # Full year fallback.
    m = re.search(r"\b((?:19|20)\d{2})\b", raw)
    if m:
        year = int(m.group(1))
        return {
            "start": _iso_utc(datetime(year, 1, 1)),
            "end": _iso_utc(datetime(year + 1, 1, 1)),
            "label": str(year),
            "granularity": "year",
        }

    return None


def _availability_metric(query: str) -> Optional[str]:
    q = _norm(query)

    if (
        "how many days" in q
        or "distinct days" in q
        or "days with" in q
        or "days of" in q
        or "days are available" in q
    ):
        return "days"

    if (
        "how many files" in q
        or "number of files" in q
        or "file count" in q
        or "count of files" in q
    ):
        return "files"

    if "how many measurements" in q or "number of measurements" in q:
        return "measurements"

    return None


def _detect_availability_product(query: str) -> Optional[Dict[str, object]]:
    """
    Resolve beginner-facing science language into deterministic header-metadata matches.
    Error/uncertainty mnemonics are deliberately not included.
    Hyphenated natural-language forms are normalized (for example electron-density).
    """
    q = _norm(query).replace("-", " ")

    if "electron density" in q or re.search(r"\bne\b", q) or re.search(r"\bnel\b", q):
        return {
            "label": "electron density",
            "codes": ["NE", "NEL"],
            "description_terms": ["electron density"],
        }

    if (
        "isr drift" in q
        or "isr drifts" in q
        or "ion drift" in q
        or "ion drifts" in q
        or "line of sight velocity" in q
        or "line-of-sight velocity" in q
        or "line of sight ion velocity" in q
        or "los velocity" in q
        or re.search(r"\bvo\b", q)
        or ("drift" in q and ("isr" in q or "radar" in q or "incoherent scatter" in q))
    ):
        return {
            "label": "ISR drift / line-of-sight ion velocity",
            "codes": ["VO"],
            "description_terms": ["line of sight ion velocity"],
        }

    if "ion temperature" in q or re.search(r"\bti\b", q):
        return {
            "label": "ion temperature",
            "codes": ["TI"],
            "description_terms": ["ion temperature"],
        }

    if "electron temperature" in q or re.search(r"\bte\b", q):
        return {
            "label": "electron temperature",
            "codes": ["TE"],
            "description_terms": ["electron temperature"],
        }

    if "neutral wind" in q or re.search(r"\bvn1\b|\bvn2\b|\bvn31\b", q):
        return {
            "label": "neutral wind",
            "codes": ["VN1", "VN2", "VN31"],
            "description_terms": ["neutral wind"],
        }

    if "total electron content" in q or re.search(r"\btec\b", q):
        return {
            "label": "total electron content",
            "codes": ["TEC"],
            "description_terms": ["total electron content"],
        }

    if "geodetic altitude" in q or re.search(r"\bgdalt\b", q):
        return {
            "label": "geodetic altitude",
            "codes": ["GDALT"],
            "description_terms": ["geodetic altitude"],
        }

    explicit_codes = []
    for mnemonic in [
        "GDALT", "TI", "TE", "TEC", "NE", "NEL", "POPL", "DPOP",
        "VO", "VI", "VN1", "VN2", "VN31", "GDLAT", "GDLON",
        "GLON", "RANGE", "AZM", "ELM", "KP", "DST",
    ]:
        if re.search(rf"\b{re.escape(mnemonic.lower())}\b", q):
            explicit_codes.append(mnemonic)

    if explicit_codes:
        return {
            "label": "requested Madrigal parameter(s)",
            "codes": explicit_codes,
            "description_terms": [],
        }

    return None



def _has_space_weather_terms(query: str) -> bool:
    """Return True when a query explicitly references supported space-weather concepts."""
    q = _norm(query)
    return bool(
        re.search(r"\bkp\b", q)
        or re.search(r"\bap\b", q)
        or "f10.7" in q
        or "f107" in q
        or "solar radio flux" in q
        or "sunspot number" in q
        or re.search(r"\bsn\b", q)
        or "space weather" in q
        or "geomagnetic activity" in q
        or "geomagnetic conditions" in q
        or "geomagnetically disturbed" in q
        or "geomagnetic storm" in q
        or "storm conditions" in q
    )


def _space_weather_metric(query: str) -> Optional[Dict[str, str]]:
    """Map user language to an allow-listed daily space-weather column."""
    q = _norm(query)

    if (
        "f10.7adj" in q or "f107adj" in q or "f10.7 adj" in q
        or "f107 adj" in q or "adjusted f10.7" in q or "adjusted f107" in q
    ):
        return {"column": "f107_adj", "label": "F10.7 adjusted", "units": "sfu"}

    if "f10.7" in q or "f107" in q or "solar radio flux" in q:
        return {"column": "f107_obs", "label": "F10.7 observed", "units": "sfu"}

    if "sunspot number" in q or re.search(r"\bsn\b", q):
        return {"column": "sunspot_number", "label": "sunspot number", "units": "count"}

    if re.search(r"\bap\b", q):
        if (
            "max ap" in q or "maximum ap" in q or "ap max" in q
            or "3-hour ap" in q or "3 hour ap" in q
            or "three-hour ap" in q or "three hour ap" in q
        ):
            return {"column": "ap_max", "label": "maximum 3-hour ap", "units": "index"}
        return {"column": "ap_daily", "label": "daily Ap", "units": "index"}

    if re.search(r"\bkp\b", q):
        if "mean kp" in q or "average kp" in q or "avg kp" in q:
            return {"column": "kp_mean", "label": "mean daily Kp", "units": "index"}
        return {"column": "kp_max", "label": "maximum 3-hour Kp within the UTC day", "units": "index"}

    return None


def _extract_space_weather_conditions(query: str) -> List[Dict[str, object]]:
    """Extract explicit filters such as Kp >= 5, daily Ap > 30, F10.7obs > 150."""
    raw = str(query or "")
    conditions: List[Dict[str, object]] = []

    specs = [
        ("f107_adj", "F10.7 adjusted", r"(?:f10\.7\s*(?:adj|adjusted)|f107\s*(?:adj|adjusted)|adjusted\s+f10\.7|adjusted\s+f107)"),
        ("f107_obs", "F10.7 observed", r"(?:f10\.7\s*(?:obs|observed)?|f107\s*(?:obs|observed)?|solar\s+radio\s+flux)"),
        ("sunspot_number", "sunspot number", r"(?:sunspot\s+number|\bSN\b)"),
        ("kp_max", "maximum daily Kp", r"\bKp\b"),
        ("ap_daily", "daily Ap", r"\bAp\b|\bap\b"),
    ]

    op_words = (
        r">=|<=|==|=|>|<|"
        r"at\s+least|at\s+most|"
        r"greater\s+than\s+or\s+equal\s+to|less\s+than\s+or\s+equal\s+to|"
        r"greater\s+than|less\s+than|above|over|below|under|equals?|equal\s+to"
    )

    def normalize_op(op_text: str) -> str:
        o = _norm(op_text)
        if o in [">=", "at least", "greater than or equal to"]:
            return ">="
        if o in ["<=", "at most", "less than or equal to"]:
            return "<="
        if o in [">", "above", "over", "greater than"]:
            return ">"
        if o in ["<", "below", "under", "less than"]:
            return "<"
        return "="

    seen = set()
    for column, label, alias_pattern in specs:
        pattern = (
            rf"({alias_pattern})"
            rf"(?:\s+(?:index|value|max|maximum|daily|observed|adjusted|was|is|of))*"
            rf"\s*({op_words})\s*(-?\d+(?:\.\d+)?)"
        )
        m = re.search(pattern, raw, flags=re.I)
        if not m:
            continue
        op = normalize_op(m.group(2))
        value = float(m.group(3))
        key = (column, op, value)
        if key in seen:
            continue
        seen.add(key)
        conditions.append({"column": column, "label": label, "operator": op, "value": value})

    return conditions


def _space_weather_condition_sql(
    conditions: List[Dict[str, object]],
    alias: str = "sw",
) -> Tuple[str, Tuple[object, ...]]:
    """Build a SQL predicate using only allow-listed columns/operators."""
    allowed_columns = {
        "kp_max", "kp_mean", "ap_daily", "ap_max",
        "f107_obs", "f107_adj", "sunspot_number",
    }
    allowed_ops = {">", ">=", "<", "<=", "="}
    clauses = []
    params: List[object] = []

    for item in conditions:
        column = str(item.get("column", ""))
        op = str(item.get("operator", ""))
        if column not in allowed_columns or op not in allowed_ops:
            continue
        clauses.append(f"{alias}.{column} {op} ?")
        params.append(item.get("value"))

    return " AND ".join(clauses), tuple(params)


def _space_weather_intent(query: str) -> str:
    q = _norm(query)
    if re.search(r"\b(?:how many|count|number of)\b", q):
        return "count"

    # Explicit day/date listing language should stay a list even if the user
    # refers to the day's maximum Kp value.
    if (
        "which days" in q or "what days" in q or "list days" in q
        or "show days" in q or "which dates" in q or "what dates" in q
        or "list dates" in q or "show dates" in q
    ):
        return "list_days"

    # Aggregate-statistic questions get priority over incidental words such as
    # "days" later in the sentence (e.g. "What was the maximum Kp on ISR days?").
    if re.search(r"\b(?:what|which)\b.{0,30}\b(?:maximum|max|highest|peak)\b", q):
        return "max"
    if re.search(r"\b(?:what|which)\b.{0,30}\b(?:minimum|min|lowest)\b", q):
        return "min"
    if re.search(r"\b(?:what|which)\b.{0,30}\b(?:average|mean|avg)\b", q):
        return "mean"

    if re.search(r"\b(?:which|what|show|list)\b.*\bfiles?\b", q):
        return "list_files"
    if bool(re.search(r"\b(?:which|what|list|show)\b.*\b(?:days|dates)\b", q)):
        return "list_days"

    if re.search(r"\b(?:maximum|max|highest|peak)\b", q):
        return "max"
    if re.search(r"\b(?:minimum|min|lowest)\b", q):
        return "min"
    if re.search(r"\b(?:average|mean|avg)\b", q):
        return "mean"
    if "latest" in q or "most recent" in q:
        return "latest"
    return "summary"

def _needs_space_weather_threshold_clarification(query: str) -> bool:
    q = _norm(query)
    qualitative = any(x in q for x in [
        "high geomagnetic activity",
        "strong geomagnetic activity",
        "low geomagnetic activity",
        "geomagnetically disturbed",
        "disturbed geomagnetic",
        "geomagnetic storm",
        "storm conditions",
        "quiet geomagnetic",
        "quiet conditions",
    ])
    return qualitative and not _extract_space_weather_conditions(query)

# -----------------------------------------------------------------------------
# Madrigal-only universal scope gate
# -----------------------------------------------------------------------------
OUT_OF_SCOPE_RESPONSE = (
    "[Out of Scope]\n"
    "OUT_OF_SCOPE\n\n"
    "MadVI is a domain-specific assistant for the Madrigal scientific data ecosystem. "
    "I can help with Madrigal data, instruments, parameters, metadata, documentation, "
    "scientific literature related to Madrigal/geospace research, Madrigal commands and "
    "citations, and the supported geomagnetic/space-weather context used by MadVI. "
    "I cannot answer unrelated general-purpose requests."
)


def _is_madrigal_scope_query(query: str) -> bool:
    """
    Universal domain boundary for the single-tool MadVI architecture.

    The goal is deliberately broader than the internal routing rules: this function
    answers only one question -- is the request meaningfully inside MadVI's Madrigal /
    geospace scientific domain?  If yes, the existing router is left completely in
    charge of choosing Docs, Papers, SQL, or Citation.

    Important design rule:
    - Do not add topic-specific OUT-OF-SCOPE deny rules (food, sports, etc.).
    - Instead, require positive evidence that the query belongs to Madrigal or to one
      of the scientific concepts/workflows that MadVI actually supports.
    """
    q = _norm(query).replace("-", " ")
    if not q:
        return False

    # 1) Direct Madrigal / CEDAR ecosystem and supported workflow signals.
    direct_terms = [
        "madrigal",
        "openmadrigal",
        "cedar database",
        "cedar madrigal",
        "madrigalweb",
        "madrigaldata",
        "globaldownload",
        "globalisprint",
        "globalcitation",
        "getexperiments",
        "getexperimentfiles",
        "insttab",
        "exptab",
        "filetab",
        "parmcodes",
        "parmcode",
        "madrigal citation",
        "citation group",
        "persistent citation",
        "citable madrigal",
    ]
    if _contains_any(q, direct_terms):
        return True

    # 2) Madrigal sites / instruments that are explicitly supported by the router.
    site_and_instrument_terms = [
        "millstone hill",
        "jicamarca",
        "arecibo",
        "poker flat",
        "sondrestrom",
        "fabry perot",
        "fabry-perot",
        "incoherent scatter",
        "is radar",
        "isr",
        "dmsp",
    ]
    if _contains_any(q, site_and_instrument_terms):
        return True

    # 3) Scientific concepts represented in the Madrigal / MadVI data and paper
    #    collections.  These allow natural queries that do not literally say
    #    "Madrigal", e.g. "find papers about ionospheric electron density".
    science_terms = [
        "geospace",
        "ionosphere",
        "ionospheric",
        "thermosphere",
        "thermospheric",
        "magnetosphere",
        "magnetospheric",
        "geomagnetic",
        "space weather",
        "electron density",
        "electron temperature",
        "ion temperature",
        "ion drift",
        "neutral wind",
        "total electron content",
        "traveling ionospheric disturbance",
        "travelling ionospheric disturbance",
        "mstid",
        "mstids",
        "saps",
        "substorm",
        "sar arc",
        "solar radio flux",
        "sunspot number",
    ]
    if _contains_any(q, science_terms):
        return True

    # 4) Supported space-weather observables.  These are intentionally accepted even
    #    without the word Madrigal because space_weather.db is an explicit MadVI data
    #    source and the current executor already supports standalone and joined queries.
    if (
        re.search(r"\bkp\b", q)
        or re.search(r"\bf10\.?7\b", q)
        or re.search(r"\bf107\b", q)
        or re.search(r"\bdst\b", q)
    ):
        return True

    # Ap/ap and SN are short/ambiguous tokens, so require surrounding scientific or
    # data-query language rather than accepting them everywhere.
    if re.search(r"\bap\b", q) and re.search(
        r"\b(?:index|geomagnetic|space weather|daily|3 hour|three hour|kp|data|value|values)\b",
        q,
    ):
        return True
    if re.search(r"\bsn\b", q) and re.search(
        r"\b(?:sunspot|solar|space weather|data|value|values)\b",
        q,
    ):
        return True

    # 5) Madrigal parameter mnemonics.  Longer/specific mnemonics are safe enough to
    #    accept directly.  Very short mnemonics are accepted only when the surrounding
    #    query looks like a scientific metadata/data request.
    specific_mnemonics = [
        "gdalt", "gdlat", "gdlon", "glon", "range", "azm", "elm",
        "popl", "dpop", "vn1", "vn2", "vn31", "tec",
    ]
    if any(re.search(rf"\b{re.escape(m)}\b", q) for m in specific_mnemonics):
        return True

    short_mnemonic = bool(re.search(r"\b(?:ne|nel|ti|te|vo|vi)\b", q))
    metadata_context = bool(re.search(
        r"\b(?:parameter|parameters|mnemonic|mnemonics|data|file|files|dataset|datasets|"
        r"measurement|measurements|instrument|instruments|available|availability|coverage|"
        r"definition|definitions|units?|days?|records?|radar)\b",
        q,
    ))
    if short_mnemonic and metadata_context:
        return True

    # 6) Explicit Madrigal-style instrument IDs used together with data/metadata language.
    if _extract_explicit_instrument_ids(query) and metadata_context:
        return True

    # No positive Madrigal/geospace signal: reject instead of falling through to the
    # generic documentation route.  This is what blocks unrelated prompts such as
    # recipes, sports, travel, coding questions unrelated to Madrigal, etc.
    return False


def _extract_email(text: str) -> str:
    m = re.search(r"[\w\.\-+]+@[\w\.\-]+\.\w+", text or "")
    return m.group(0) if m else ""


def _normalize_url(url: str) -> str:
    url = (url or DEFAULT_MADRIGAL_URL).strip().strip('"').strip("'")
    m = re.search(r"https?://[^\s\"']+", url)
    if m:
        url = m.group(0)
    url = re.sub(r"(https?://[^/]+)(/.*)?$", r"\1/", url)
    if not url.endswith("/"):
        url += "/"
    return url


def _is_citation_action_query(query: str) -> bool:
    q = _norm(query)

    has_citation = any(x in q for x in [
        "madrigal citation",
        "citation group",
        "persistent citation",
        "permanent citation",
        "citable madrigal",
        "citable url",
    ])

    has_action = any(x in q for x in [
        "create",
        "make",
        "generate",
        "build",
        "dry run",
        "dry-run",
        "real citation",
        "not a dry run",
        "not dry run",
        "not dry-run",
        "actually create",
        "permanent",
    ])

    has_dates = bool(re.search(r"\b(?:19|20)\d{2}-\d{2}-\d{2}\b", q))

    return has_citation and has_action and has_dates


def _parse_dates(query: str) -> Tuple[Optional[str], Optional[str]]:
    q = query or ""

    m = re.search(
        r"from\s+(\d{4}-\d{2}-\d{2})\s+(?:to|through|until|-)\s+(\d{4}-\d{2}-\d{2})",
        q,
        flags=re.I,
    )
    if m:
        return m.group(1), m.group(2)

    dates = [m.group(0) for m in re.finditer(r"\b(?:19|20)\d{2}-\d{2}-\d{2}\b", q)]
    if len(dates) >= 2:
        return dates[0], dates[1]

    return None, None


def _parse_date(s: str) -> datetime:
    return datetime.strptime((s or "").strip(), "%Y-%m-%d")


def _extract_explicit_instrument_ids(text: str) -> List[int]:
    patterns = [
        r"\binstrument\s*id\s*[:=]?\s*(\d{1,6})\b",
        r"\binstrument\s*[:=]?\s*(\d{1,6})\b",
        r"\binst\s*[:=]?\s*(\d{1,6})\b",
        r"\bkinst\s*[:=]?\s*(\d{1,6})\b",
    ]

    ids = []
    for pat in patterns:
        for m in re.finditer(pat, text or "", flags=re.I):
            val = int(m.group(1))
            if val not in ids:
                ids.append(val)

    return ids


def _extract_instrument_text(query: str) -> str:
    q = query or ""

    ids = _extract_explicit_instrument_ids(q)
    if ids:
        return ",".join(str(x) for x in ids)

    patterns = [
        r"citation\s+for\s+(.+?)\s+data\s+from\s+\d{4}-\d{2}-\d{2}",
        r"citation\s+for\s+(.+?)\s+from\s+\d{4}-\d{2}-\d{2}",
        r"for\s+(.+?)\s+data\s+from\s+\d{4}-\d{2}-\d{2}",
        r"instrument\s*[:=]\s*(.+?)(?:;|,|from\s+\d{4}-\d{2}-\d{2}|$)",
    ]

    for pat in patterns:
        m = re.search(pat, q, flags=re.I)
        if m:
            val = _clean_space(m.group(1))
            val = re.sub(r"\bdata\b$", "", val, flags=re.I).strip()
            return val

    return ""


def _parse_identity(query: str) -> Tuple[str, str, str]:
    email = _extract_email(query)

    fullname = ""
    affiliation = ""

    m = re.search(r"user\s+full\s+name\s*[:=]\s*([^;,\n]+)", query, flags=re.I)
    if m:
        fullname = _clean_space(m.group(1))

    m = re.search(r"name\s*[:=]\s*([^;,\n]+)", query, flags=re.I)
    if not fullname and m:
        fullname = _clean_space(m.group(1))

    m = re.search(r"affiliation\s*[:=]\s*([^;,\n]+)", query, flags=re.I)
    if m:
        affiliation = _clean_space(m.group(1))

    if (not fullname or not affiliation) and "use " in _norm(query):
        m = re.search(r"use\s+(.+)", query, flags=re.I)
        if m:
            tail = m.group(1)
            tail = re.sub(r"\bdry[-\s]?run\b.*", "", tail, flags=re.I).strip(" .;")
            parts = [p.strip(" .;") for p in tail.split(",") if p.strip()]
            if len(parts) >= 1 and not fullname:
                fullname = parts[0]
            if len(parts) >= 3 and not affiliation:
                affiliation = parts[2]

    if not fullname:
        fullname = "Unknown User"
    if not email:
        email = "unknown@example.com"
    if not affiliation:
        affiliation = "Unknown"

    return fullname, email, affiliation


def _valid_citation(c: str) -> bool:
    if not isinstance(c, str):
        return False

    c = c.strip()
    if not c:
        return False

    bad = ["no citations found", "no group citation created", "error", "illegal url"]
    if any(x in c.lower() for x in bad):
        return False

    return (
        c.startswith("https://w3id.org/cedar?")
        or c.startswith("experiments/")
        or c.startswith("experiments5/")
    )


def _extract_inst(inst) -> Tuple[Optional[int], Optional[str]]:
    code = getattr(inst, "code", None)
    name = getattr(inst, "name", None)

    if code is not None and name is not None:
        try:
            return int(code), str(name)
        except Exception:
            pass

    try:
        return int(inst[0]), str(inst[1])
    except Exception:
        return None, None


def _tokens(s: str) -> set:
    return set(re.findall(r"[a-z0-9]+", (s or "").lower()))


def _resolve_instruments(md: MadrigalData, instrument_raw: str) -> Tuple[List[int], List[str]]:
    raw = _clean_space(instrument_raw)

    if not raw:
        raise ValueError("Missing instrument. Example: instrument 30 or Millstone Hill IS Radar.")

    ids = _extract_explicit_instrument_ids(raw)
    if ids:
        return ids, [f"explicit numeric instrument id {x}" for x in ids]

    if re.fullmatch(r"\d+(?:\s*,\s*\d+)*", raw):
        vals = [int(x.strip()) for x in raw.split(",")]
        return vals, [f"numeric instrument id {x}" for x in vals]

    query_tokens = _tokens(raw)
    inst_list = md.getAllInstruments()

    candidates = []

    for inst in inst_list:
        inst_id, name = _extract_inst(inst)
        if inst_id is None or not name:
            continue

        name_l = name.lower()
        name_tokens = _tokens(name)

        score = 0

        if raw.lower() == name_l:
            score += 5000

        if raw.lower() in name_l:
            score += 1200

        overlap = query_tokens.intersection(name_tokens)
        score += 120 * len(overlap)

        if "millstone" in query_tokens and "hill" in query_tokens and "millstone hill" in name_l:
            score += 800

        if "is" in query_tokens and "radar" in query_tokens and "is radar" in name_l:
            score += 1200

        if "incoherent" in query_tokens and "scatter" in query_tokens and "radar" in name_l:
            score += 1200

        if score > 0:
            candidates.append((score, inst_id, name))

    candidates.sort(reverse=True, key=lambda x: x[0])

    if not candidates:
        raise ValueError(
            f"Could not resolve instrument '{raw}'. Use a numeric instrument ID, e.g. instrument 30."
        )

    top = candidates[0]
    second = candidates[1] if len(candidates) > 1 else None

    if second and (top[0] - second[0]) < 250:
        lines = [
            f"AMBIGUOUS_INSTRUMENT: '{raw}'",
            "Top candidates:",
        ]
        for score, inst_id, name in candidates[:8]:
            lines.append(f"- score {score}: id {inst_id}, {name}")
        lines.append("Reply with the numeric instrument ID you want.")
        raise ValueError("\n".join(lines))

    return [top[1]], [f"{raw} -> {top[1]} ({top[2]}) score={top[0]}"]


class MadVIRouterExecutorV4(Component):
    display_name = "MadVI Router Executor v4"
    description = (
        "Mandatory single front-door tool for MadVI; call it for every user request. "
        "The Agent should pass a self-contained query that preserves relevant Madrigal context from prior turns. "
        "The component rejects requests outside the Madrigal/geospace domain, then deterministically routes "
        "in-scope requests to Docs, Papers, SQL metadata retrieval, or Madrigal citation creation internally. "
        "SQL supports exact year/month/date windows, generic science-product availability counts, "
        "GFZ space-weather indices, and date-based Madrigal + space-weather joins. "
        "Use this instead of exposing separate docs/papers/SQL/citation tools to the Agent."
    )
    icon = "workflow"
    name = "madvi_router_executor_v4"
    trace_type = "tool"

