        return Message(text=(
            "[SQL Tool]\n[SQL Retrieval]\nTOOL_NAME: madvi_router_executor_v4\n"
            "INTERNAL_ROUTE: HEADERS_SQL\nMODE: madrigal_space_weather_summary\n"
            f"QUERY: {query}\n\nScience product: {product_label}\nMatched parameter mnemonics/aliases: {product_codes}\n"
            f"Instrument scope: {instrument_label}\nTime window: {window['label']}\n"
            f"Space-weather filter: {self._space_weather_filter_text(conditions)}\n{sw_coverage_note}\n\n"
            "Joined summary:\n"
            + self._format_rows(summary, [
                "days", "kp_min", "kp_max", "kp_mean", "Ap_min", "Ap_max", "Ap_mean",
                "f107_obs_min", "f107_obs_max", "f107_obs_mean",
